DROP TABLE IF EXISTS events;
DROP TABLE IF EXISTS subscriptions;
DROP TABLE IF EXISTS bids;
DROP TABLE IF EXISTS invitations;
DROP TABLE IF EXISTS tenders;
DROP TABLE IF EXISTS projects;
DROP TABLE IF EXISTS companies;

CREATE TABLE companies (
  company_id   INTEGER PRIMARY KEY,
  name         VARCHAR NOT NULL,
  company_type VARCHAR NOT NULL,   -- 'gc' (general contractor) or 'sub' (subcontractor)
  country      VARCHAR NOT NULL,
  signed_up_at DATE NOT NULL
);

CREATE TABLE projects (
  project_id    INTEGER PRIMARY KEY,
  gc_company_id INTEGER NOT NULL,
  name          VARCHAR NOT NULL,
  region        VARCHAR NOT NULL,
  budget_eur    NUMERIC(12,2),
  status        VARCHAR NOT NULL,  -- 'draft','active','completed','cancelled'
  created_at    DATE NOT NULL
);

CREATE TABLE tenders (
  tender_id    INTEGER PRIMARY KEY,
  project_id   INTEGER NOT NULL,
  trade        VARCHAR NOT NULL,   -- 'electrical','plumbing','earthworks',...
  published_at DATE,
  deadline_at  DATE,
  status       VARCHAR NOT NULL    -- 'draft','published','awarded','cancelled'
);

CREATE TABLE invitations (
  invitation_id  INTEGER PRIMARY KEY,
  tender_id      INTEGER NOT NULL,
  sub_company_id INTEGER NOT NULL,
  sent_at        TIMESTAMP NOT NULL,
  opened_at      TIMESTAMP,
  responded_at   TIMESTAMP
);

CREATE TABLE bids (
  bid_id         INTEGER PRIMARY KEY,
  tender_id      INTEGER NOT NULL,
  sub_company_id INTEGER NOT NULL,
  amount_eur     NUMERIC(12,2) NOT NULL,
  submitted_at   TIMESTAMP NOT NULL,
  is_winner      BOOLEAN NOT NULL
);

CREATE TABLE subscriptions (
  subscription_id INTEGER PRIMARY KEY,
  company_id      INTEGER NOT NULL,
  plan            VARCHAR NOT NULL,   -- 'starter','pro','enterprise'
  mrr_eur         NUMERIC(10,2) NOT NULL,
  started_on      DATE NOT NULL,
  ended_on        DATE                -- NULL = still active
);

CREATE TABLE events (
  event_id    INTEGER PRIMARY KEY,
  company_id  INTEGER NOT NULL,
  user_id     INTEGER NOT NULL,
  event_name  VARCHAR NOT NULL,
  occurred_at TIMESTAMP NOT NULL
);

